ee:variables.ee:set-variable:
%dw 2.0
output application/java
var response = read(payload as String {encoding: "windows-1252"}, "application/xml")
var cursor = response.TBL.@next default null
---
{
	rows: (response.TBL.*CLI default []) map ((row) -> {
		code: trim((row.TypeCode default "") as String),
		name: trim((row.TypeName default "") as String)
	}),
	next:
		if (cursor == null or isBlank(cursor as String))
			null
		else
			cursor as String
}
